:root {
  font-family: system-ui, sans-serif;
  color: #1c2d40;
  background: #f4f6fa;
}
body { margin: 0; }
main {
  max-width: 760px;
  margin: 48px auto;
  padding: 28px;
  background: white;
  border-radius: 12px;
  box-shadow: 0 4px 24px #1c2d4010;
}
h1 { margin-top: 0; }
form { display: flex; flex-wrap: wrap; align-items: center; gap: 12px; }
form + form { margin-top: 24px; }
label { font-weight: 600; }
input, button, select { font: inherit; padding: 10px 14px; border-radius: 6px; }
input { border: 1px solid #8794a3; min-width: 0; }
button { border: 1px solid #2459a6; background: #2459a6; color: white; cursor: pointer; }
button:hover { background: #194783; }
button:disabled { opacity: .6; cursor: not-allowed; }
:focus-visible { outline: 3px solid #da8900; outline-offset: 3px; }
ul { list-style: none; padding: 0; margin-top: 28px; }
li { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 16px; padding: 16px 0; border-bottom: 1px solid #dce2eb; }
li span { overflow-wrap: anywhere; }
input[type="checkbox"] { width: 20px; height: 20px; padding: 0; flex-shrink: 0; }
.task-filter { display: flex; align-items: center; gap: 12px; margin-top: 24px; }
[role="alert"] { color: #a51b26; }
@media (max-width: 600px) {
  main { margin: 16px; padding: 20px; }
  form { align-items: stretch; flex-direction: column; }
}

